class Solution {
public:
    int minimumLength(string s) {
        string st;
        for (char c : s) {
            if (!st.empty() && st.back() != c) st.pop_back();
            else st.push_back(c);
        }
        return st.size();
    }
};

c.java:
class Solution {
    public int minimumLength(String s) {
        StringBuilder st = new StringBuilder();
        for (char c : s.toCharArray()) {
            int n = st.length();
            if (n > 0 && st.charAt(n - 1) != c) st.deleteCharAt(n - 1);
            else st.append(c);
        }
        return st.length();
    }
}

